    close.save(E/'r0018-brow-closeup-comparison.png')
    triangleInvariant={name:len({x['triangleIndexSha256'] for x in diagnosis['quadSurfaceAcrossPoses'] if x['object']==name})==1 for name in ('AFN11_L_BrowFibres','AFN11_R_BrowFibres')}
    assert all(triangleInvariant.values())
    save('diagnostic-conclusions.json',{'materialOnly':'Original saved dark-brown ramp and link are correct. Constant dark diffuse makes only small ROI changes and does not fix sparse fine-stroke readability.','tessellationHypothesis':'FALSIFIED as the explanation for pose-dependent contacts: the evaluated triangle index arrays were already unchanged across tested poses. Explicit triangles make the stored primitive definition unambiguous, but did not alone resolve the contacts.','contactResolution':'A right-brow strand was removed in B. C additionally scans all five poses before culling two localized left-brow strands; remaining vertices, pigments and weights are unchanged. Independent final checks pass.','limits':'No general Blender bug, continuous separation, physical hair density or objective realism claim is established.'})
    next_action=('Use workingReviewSource r0018 C as the integrated full-head research source; it includes r0017 C scalp hair plus the new 1080-fibre brows. Keep r0017 hair geometry and the new brows fixed instead of running another brow-density or pigment sweep. Next advance the complete-head milestone by inspecting actual lid topology, eye optics, rig and existing shape-key support for a blink. Establish open, half-closed and closed lid contours and thickness against the actual cornea before authoring independent left/right blink controls. Lash roots must follow evaluated eyelid skin rather than remain frozen to the head. Test closure/reopening and transition contact with the eye surfaces and complete finite-radius lash geometry, using swept/continuous evidence or justified bounded substeps; static samples alone do not qualify a blink. Do not move the eyeballs, change exposure or add a covering strip to hide closure defects. Preserve the full-face neutral appearance and correct topology if a local deformation cannot produce a valid closure; do not revive the rejected radial annulus method. The r0018 brow/contact proof is five static poses only; the original head/eye/lash/hair state is inherited only where unchanged. For future strand repairs, collect all required-pose offenders in one bounded diagnosis rather than fixing only the first failed pose. Triangulation changes did not explain this case, so do not keep searching that cause. Hairline/part/ends, scalp-hair dynamics/self contact, expressions/oral components, full body/clothes and native runtime/LOD/performance remain incomplete. No male or formal runtime/site promotion before full female gates and user acceptance.')
    audit={'revision':'female-next-r0018','status':'BROW_READABILITY_RESEARCH_RETAINED_CHANGED_GEOMETRY_STATIC_GATES_ONLY','selectedCandidate':'C','workingReviewSource':build['output'],
        'candidateDecisions':{'A':'REJECTED: readable layered field, but four neutral nonadjacent triangle pairs intersect between two right-brow strands.','B':'REJECTED: one offending strand removed, passes neutral and gaze cases, but turn-left exposes left-brow contacts. No partial-pose acceptance.','C':'RESEARCH_RETAINED: stored explicit triangles, all-pose localized culling of two additional strands, 1080 final fibres; independent five-pose checks and controlled face/closeup/oblique/side-light images pass.'},
        'actualVisibleGain':'Brows read more clearly in the full face and retain individual fibre structure. Original skin albedo, brow pigment, scalp hair, eyes and exposure are unchanged. This is a local appearance gain, not a photorealistic-face acceptance.',
        'strictBrowAppearanceEstimate':{'score':55,'uncertaintyPoints':10,'scope':'Subjective static brow appearance only, assessed at whole-face and closeup views with two lighting setups. Not the face/eye category or overall score.','deductions':['Fibres remain too uniformly stroke-like, particularly at the inner ends.','Brow heads and tails need more natural edge variation.','Fine detail loses readability at distance; runtime filtering/LOD is unqualified.']},
        'overallCharacterScore':None,'verified':{'sourceFibres':637,'candidateAFibres':1083,'candidateBFibres':1082,'finalFibres':sum(x['fibres'] for x in build['layers']),'allFinalBrowFacesTriangles':True,'headSkinEyesLashesHairRigLightAndMaterialStateUnchanged':True,'staticPoses':list(proof['poses']),'minimumSampledBrowVertexBodyGapM':min(x['minimumSampledVertexBodyGapM'] for p in proof['poses'].values() for x in p['brows'].values()),'distanceScope':'Sampled vertices to actual body triangles, not global surface minimum. Complete triangle overlap/outside connected-anchor checks plus finite-radius scalp-hair vs new-brow surface checks have their own reported scopes.','displayROIMetrics':metrics['rows'],'quadTriangleIndicesWereAlreadyStable':triangleInvariant},
        'remainingGates':['Not photorealistic; face/eye anatomy, skin and hair visual defects remain.','No blink, brow expressions or continuous motion certificate; no complete scalp-hair dynamics/self collision.','No native runtime/LOD/performance, full body/clothes or final user acceptance.'],'nextAction':next_action,'runtimePromotionApproved':False,'websitePromotionApproved':False}
