    save('continuation.json',{'stage':'B_COMPLETE_HEAD_IN_PROGRESS','lastGoalTurnClassification':'progress','classificationReason':'Saved material/footprint diagnostics distinguish coverage from pigment. New brow geometry visibly improves full-face readability. Two contact failures retained; final explicitly defined surfaces and targeted all-pose strand removal pass independent checks. No overall-quality or complete-motion promotion.','currentFullGroomInput':build['output'],'workingReviewSource':build['output'],'sourceHairGeometryRevision':'female-next-r0017-c','browBindings':build['browBindings'],'liveJobHandles':[],'nextAction':next_action,'doNotRepeat':['Pigment-only darkening to fix sparse brow coverage.','Unbounded brow density or a fourth r0018 style candidate.','Fixing only the first failed pose without collecting the remaining required pose offenders.','Claiming tessellation varied here; the measured triangle IDs were stable.','The stopped radial perioral annulus and infeasible single turning-root convex proxy.'],'remainingGates':audit['remainingGates'],'overallCharacterScore':None})
    save('references.json',{'officialDocs':['https://docs.blender.org/manual/en/5.4/render/shader_nodes/input/attribute.html','https://docs.blender.org/manual/en/latest/render/eevee/index.html'],'use':'General attribute-node and renderer semantics only. Actual saved graphs, floats, palette and evaluated geometry were inspected in installed Blender 5.2.2; no behavior inferred solely from a different manual version.','assets':'No new external assets or code. Existing packed CC0 skin/body provenance remains inherited; all new fibre geometry and authoring/verification scripts are local work.'})
    save('execution-notes.json',{'initialCConstructionError':'KeyError head after assigning a new mesh without recreating the vertex-group definitions. No C artifact had been saved; definitions recreated by name, then successful saved-state/weight checks and independent verification completed. Original error log retained.','repairBMetadata':'Repair duration was not measured; inherited A duration removed instead of reporting it as B timing.','repairWitnessEfficiency':'An accidental quadratic witness-list construction was simplified to a single linear copy; produced witness/geometry semantics unchanged.'})
    manifest=read(M);assert manifest['runtimeAsset'] is None and manifest['currentSourceRevision']=='female-next-r0001'
    manifest.update({'latestStudyRevision':'female-next-r0018','latestStudyStatus':audit['status'],'latestStudyEvidence':str(E/'female-next-r0018-brows.visual-audit.json'),'workingReviewRevision':'female-next-r0018-c','workingReviewSource':'source/'+Path(build['output']).name,'workingReviewSha256':build['outputSha256'],'workingReviewStatus':'INTEGRATED_PARTIAL_HEAD_RESEARCH_NOT_PROMOTED','headDetailResearchSource':'source/'+Path(build['output']).name,'headDetailResearchScope':'r0018 C integrated head: 1080 newly authored brow fibres with original skin, optics/lashes and r0017 C scalp hair held. Changed brows and scalp-hair/new-brow pairs checked in five static poses; no expression/continuous-motion or full-face acceptance.','browResearchSource':'source/'+Path(build['output']).name,'browAuthoringBindings':'source/'+Path(build['browBindings']).name,'nextRequiredWork':next_action})
